FROM public.profile_systems s
WHERE s.code='DEMO_60' AND s.is_global=TRUE
  AND NOT EXISTS (
    SELECT 1 FROM public.handle_requirement_policies p
    WHERE p.system_id=s.id AND p.org_id IS NULL AND p.version=2)
  AND NOT EXISTS (
    SELECT 1 FROM public.handle_requirement_policies p
    CROSS JOIN LATERAL jsonb_array_elements(p.authority->'slots') slot
    WHERE p.system_id=s.id AND p.org_id IS NULL
      AND slot->>'leaf_handedness' IS NOT NULL)
ON CONFLICT (id) DO NOTHING;

